            <button type="submit">Create project</button>
          </div>
          <p id="form-alert" class="alert" role="alert" hidden></p>
        </form>
        <div id="projects" class="projects" aria-live="polite"></div>
      </section>
      <section id="project-detail" aria-labelledby="detail-title" hidden>
        <button id="back-to-projects" class="back-button" type="button">Projects</button>
        <h1 id="detail-title"></h1>
      </section>
    </main>
  </body>
